tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "get_alignment_targets",
    "description": "Die betroffenen PBIs (pbiId, aktueller Titel/Statement/Akzeptanzkriterien) plus die ausloesenden Anforderungen (requirementId, neueFassung, alteFassung).",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "save_alignments",
    "description": "Speichert je Ziel GENAU EINEN Draft (proposedTitle, proposedStatement, proposedAcceptanceCriteria, rationale, triggerRequirementIds). Bei bestehendem PBID: pbiId setzen. Bei einem NEUEN PBI (zielRequirementId war gesetzt, pbiId war null): pbiId LEER lassen und stattdessen targetRequirementId (\u002B targetFeatureId) setzen. Genau einmal aufrufen.",
    "parameters": {
      "type": "object",
      "properties": {
        "alignments": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "pbiId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "proposedTitle": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "proposedStatement": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "proposedAcceptanceCriteria": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": "string"
              },
              "triggerRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "targetRequirementId": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              },
              "targetFeatureId": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
              "pbiId",
              "proposedTitle",
              "proposedStatement",
              "proposedAcceptanceCriteria",
              "rationale",
              "triggerRequirementIds"
            ]
          }
        }
      },
      "required": [
        "alignments"
      ]
    }
  }
]

